/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE knowledge_metadata (
                    id TEXT PRIMARY KEY,
                    filename TEXT NOT NULL,
                    category TEXT NOT NULL,
                    title TEXT NOT NULL,
                    sub_type TEXT,
                    tradition TEXT,
                    step TEXT,
                    size_bytes INTEGER,
                    line_count INTEGER,
                    sources_ref_json TEXT,
                    claims_ref_json TEXT,
                    steps_ref_json TEXT,
                    status TEXT,
                    content_hash TEXT,
                    updated_at REAL
                );
CREATE TABLE IF NOT EXISTS 'knowledge_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'knowledge_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'knowledge_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3, c4, c5, c6);
CREATE TABLE IF NOT EXISTS 'knowledge_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'knowledge_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE youtube_catalog (
    id TEXT PRIMARY KEY,
    video_number INTEGER,
    video_id TEXT NOT NULL,
    url TEXT NOT NULL,
    title TEXT NOT NULL,
    primary_theme TEXT,
    all_themes_json TEXT
);
CREATE TABLE IF NOT EXISTS 'youtube_catalog_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'youtube_catalog_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'youtube_catalog_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3, c4, c5);
CREATE TABLE IF NOT EXISTS 'youtube_catalog_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'youtube_catalog_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
ANALYZE sqlite_schema;
PRAGMA writable_schema=ON;
                    id UNINDEXED,
                    category UNINDEXED,
                    tradition UNINDEXED,
                    step UNINDEXED,
                    title,
                    summary,
                    content,
                    tokenize = ''porter unicode61''
                )');
    video_id UNINDEXED,
    video_number UNINDEXED,
    url UNINDEXED,
    title,
    primary_theme,
    all_themes,
    tokenize = ''porter unicode61''
)');
CREATE TABLE task_queue (
    id TEXT PRIMARY KEY,
    video_number INTEGER NOT NULL UNIQUE,
    video_id TEXT NOT NULL,
    url TEXT NOT NULL,
    title TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'QUEUED',
    attempts INTEGER NOT NULL DEFAULT 0,
    last_attempt TEXT,
    completed_at TEXT,
    error_log TEXT,
    dialogue_turns_count INTEGER DEFAULT 0
);
CREATE TABLE arena_users (
        user_id TEXT PRIMARY KEY,
        email TEXT UNIQUE,
        name TEXT,
        avatar_url TEXT,
        bio TEXT,
        role TEXT DEFAULT 'visitor',
        dana TEXT DEFAULT '',
        gopay TEXT DEFAULT '',
        shopeepay TEXT DEFAULT '',
        ovo TEXT DEFAULT '',
        qris_url TEXT DEFAULT '',
        total_donations_received INTEGER DEFAULT 0,
        created_at TEXT
    );
CREATE TABLE arena_donations (
        id TEXT PRIMARY KEY,
        donor_user_id TEXT,
        donor_name TEXT,
        donor_avatar TEXT,
        recipient_user_id TEXT,
        recipient_name TEXT,
        gross_amount INTEGER,
        platform_fee_10pct INTEGER,
        recipient_net_90pct INTEGER,
        payment_method TEXT,
        message TEXT,
        status TEXT DEFAULT 'PAID',
        timestamp TEXT
    );
CREATE TABLE arena_wallet_balances (
        user_id TEXT PRIMARY KEY,
        balance_net INTEGER DEFAULT 0,
        total_withdrawn INTEGER DEFAULT 0,
        updated_at TEXT
    );
CREATE TABLE arena_platform_treasury (
        id INTEGER PRIMARY KEY,
        total_fee_collected INTEGER DEFAULT 0,
        updated_at TEXT
    );
CREATE TABLE arena_chat_messages (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        user_name TEXT,
        user_avatar TEXT,
        message TEXT,
        is_system INTEGER DEFAULT 0,
        timestamp TEXT
    );
CREATE TABLE social_posts (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        user_name TEXT,
        user_avatar TEXT,
        user_badge TEXT DEFAULT 'Debater',
        media_type TEXT, -- 'photo', 'video', 'text', 'audio'
        media_url TEXT,
        caption TEXT,
        music_title TEXT DEFAULT '',
        music_url TEXT DEFAULT '',
        tags TEXT DEFAULT '',
        likes_count INTEGER DEFAULT 0,
        comments_count INTEGER DEFAULT 0,
        created_at TEXT
    );
CREATE TABLE social_comments (
        id TEXT PRIMARY KEY,
        post_id TEXT,
        user_id TEXT,
        user_name TEXT,
        user_avatar TEXT,
        comment TEXT,
        created_at TEXT
    );
CREATE TABLE social_likes (
        user_id TEXT,
        post_id TEXT,
        created_at TEXT,
        PRIMARY KEY (user_id, post_id)
    );
CREATE TABLE social_stories (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        user_name TEXT,
        user_avatar TEXT,
        content TEXT,
        media_url TEXT,
        media_type TEXT DEFAULT 'text',
        bg_gradient TEXT DEFAULT 'from-purple-600 to-indigo-600',
        created_at TEXT
    );
CREATE INDEX idx_meta_category ON knowledge_metadata(category)
            ;
CREATE INDEX idx_meta_tradition ON knowledge_metadata(tradition)
            ;
CREATE INDEX idx_meta_step ON knowledge_metadata(step)
            ;
CREATE INDEX idx_task_queue_status ON task_queue(status, video_number);
PRAGMA writable_schema=OFF;
COMMIT;
